 */
export function roundingFor(claim: Claim, rules: DueRules): Rounding {
  const date = claim.corrects !== null ? (rules.claimDates.get(claim.corrects) ?? claim.date) : claim.date;
  return date < rules.policyDate ? 'half-up' : 'half-even';
}

/**
 * An amount times a percent rate, divided by 100, rounded to two decimals (half to even unless told
 * otherwise); n/a with no rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined, rounding: Rounding = 'half-even'): string {
  if (rate === undefined) return NA;
  return percentOf(hundredths(amount), hundredths(rate), rounding);
}

/** Cents times basis points / 10000, rounded to two decimals as told. */
function percentOf(amountCents: number, basisPoints: number, rounding: Rounding): string {
  const product = amountCents * basisPoints;
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && (rounding === 'half-up' || whole % 2 === 1));
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}

/** A due raised to the floor (both two decimals); n/a stays n/a. */
export function floored(value: string, floor: string): string {
  return value !== NA && hundredths(value) < hundredths(floor) ? Number(floor).toFixed(2) : value;
}

/**
 * A claim's figure: the figure its statement bound it to (not while PENDING), else its amount at the rate in force on its
 * date for the person's grade in force on that date, rounded by the policy date — no floor.
 */
function claimFigure(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (bound(claim)) return claim.statedDue ?? NA;
  return due(claim.amount, rateFor(rates, gradeOn(grades, claim.date), claim.date), roundingFor(claim, rules));
}

/**
 * The late charge on a figure: for every full 30 days the claim is overdue, the late percent in force on that boundary date
 * (its due-by plus 30, 60, 90 ... days) of it, rounded like the claim's due, the charges added up (a boundary at 0.00 adds
 * nothing); 0.00 when it is not overdue, and always for a correction.
 */
export function lateCharge(claim: Claim, figure: string, rules: DueRules): string {
  if (claim.corrects !== null) return '0.00';
  const periods = latePeriods(claim, rules.today);
  const charges: string[] = [];
  for (let period = 1; period <= periods; period++) {
    const pct = hundredths(rules.latePctOn(lateBoundary(claim, period)));
    if (pct !== 0) charges.push(percentOf(hundredths(figure), pct, roundingFor(claim, rules)));
  }
  return total(charges);
}

/**
 * A claim's due: the one fixed when it was settled (any late charge and floor frozen in), else the greater of the
 * floor in force on its date and its figure plus the late charge on it while it is overdue — a correction has no
 * floor and no charge. Neither the charge nor the floor is bound by a statement: they follow the sheet's today.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules);
  if (figure === NA || claim.corrects !== null) return figure;
  return floored(total([figure, lateCharge(claim, figure, rules)]), rules.floorOn(claim.date));
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (bound(c) && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. Their open claims a hold covers (not bound by a statement) do not count. It is at most the
 * sheet's cap (n/a is not capped).
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const sum = personSum(claims, rates, grades, holds, rules);
  if (sum === NA || rules.cap === '' || hundredths(sum) <= hundredths(rules.cap)) return sum;
  return rules.cap;
}

/** A person's excess: by how much their due-total is above the sheet's cap; 0.00 when it is not (or is n/a). */
export function personExcess(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const sum = personSum(claims, rates, grades, holds, rules);
  if (sum === NA || rules.cap === '') return '0.00';
  return (Math.max(0, hundredths(sum) - hundredths(rules.cap)) / 100).toFixed(2);
}

/** A person's due-total before the cap: their counting claims' figures added up, or n/a. */
function personSum(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): string {
  const counted = claims.filter((c) => counts(c, holds, rules.today));
  const figures = counted.map((c) => claimDue(c, rates, grades, rules));
  const anyFigure = counted.some(keepsFigure) || figures.some((f) => f !== NA);
  if (rateFor(rates, gradeOn(grades, rules.today), rules.today) === undefined && !anyFigure) {
    return NA;
  }
  return total(figures);
}

/** Dues added up, skipping n/a; with two decimals, added in cents so it is exact. */
export function total(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0);
  return (cents / 100).toFixed(2);
}

/**
 * A sheet's due-total or overdue-total: the people's figures added up, skipping n/a — leaving out the single
 * highest and the single lowest figure when three or more people have one.
 */
export function trimmedTotal(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).map(hundredths).sort((a, b) => a - b);
  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
  return (kept.reduce((sum, c) => sum + c, 0) / 100).toFixed(2);
}

/**
 * A person's settled-total and open-total: the dues of their SETTLED claims that count (at their frozen figures,
 * corrections included), and of their OPEN and PENDING ones that count, each added up (skipping n/a, not capped) —
 * together their due-total before the cap.
 */
export function personSplit(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): { settled: string; open: string } {
  const counted = claims.filter((c) => counts(c, holds, rules.today));
  const dues = (keep: (c: Claim) => boolean) =>
    total(counted.filter(keep).map((c) => claimDue(c, rates, grades, rules)));
  return { settled: dues((c) => c.status === 'SETTLED'), open: dues((c) => c.status !== 'SETTLED') };
}
import { useCallback, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';

/** A role given to a user name: clerk, steward or viewer (sees everything, changes nothing). A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the terms set
 * for each grade that has its own (by grade; any other grade uses the sheet's terms), the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), the entry date (yyyy-MM-dd; '': off — a new claim left without a date takes it instead of the
 * sheet's today), the cap (two decimals; '': none — a person's due-total is at most it), the proof threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is settled or approved only once it has a proof), the note threshold (two decimals; '': none — a
 * claim whose due is above the one in force on its date is opened only with a note), and the roles
 * given to user names. The clerk limit, floor, terms, grade terms, late percent, cap, proof threshold and note threshold are those in force on the sheet's
 * today; `history` holds every value recorded for them, by key (floor, late-pct, terms, terms-<grade>, clerk-limit,
 * cap, proof-threshold, note-threshold), oldest from-date first (value '': blank). `permissions` is the permission matrix: by action, the
 * roles allowed it, comma separated ('': blank, the standing rule); it is not dated.
 * `graceDays` is the grace days (whole days; '': off — when the sheet's today is changed, an open period whose
 * to-date plus them is before the new today is closed); it is not dated.
 * `delegations` is the steward role delegated to user names, in the order made.
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; gradeTerms: Record<string, number>; latePct: string; policyDate: string; periodNumberingFrom: string; entryDate: string; cap: string; proofThreshold: string; noteThreshold: string; roles: UserRole[]; history: Record<string, FromValue[]>; permissions: Record<string, string>; graceDays: string; delegations: Delegation[] };

/**
 * The steward role delegated by a steward (`by`) to a user name, from a from-date to a to-date (yyyy-MM-dd), both
 * inclusive: while the sheet's today is inside them the user acts as a steward.
 */
export type Delegation = { user: string; from: string; to: string; by: string };

/** A dated setting's value recorded from a date (yyyy-MM-dd); '': blank. */
export type FromValue = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else `start`. */
export function valueOn(history: FromValue[] | undefined, date: string, start: string): string {
  let found = start;
  for (const v of history ?? []) {
    if (v.from <= date) found = v.value === '' ? start : v.value;
  }
  return found;
}

/** The floor a sheet starts with: a claim's live due is at least it. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days: a claim is due by its date plus them. */
export const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The roles a user name can be given. */
export const ROLES = ['clerk', 'steward', 'viewer'];

/** The actions the permission matrix covers. */
export const PERMISSION_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'];

/** The roles allowed an action when its permission entry is blank. */
export const STANDING_PERMISSIONS: Record<string, string> = {
  open: 'clerk,steward',
  settle: 'clerk,steward',
  void: 'clerk,steward',
  reassign: 'steward',
  close: 'clerk,steward',
  reopen: 'steward',
};

/** Roles as a permission entry takes them: clerk or steward, comma separated. */
export const ROLE_LIST = /^\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*$/i;

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}


/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the floor and late percent in force on a claim's date, the sheet's today, its policy
 * date in force (blank: today), its cap in force on today ('': none) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floorOn: (date: string) => string;
  latePctOn: (date: string) => string;
  today: string;
  policyDate: string;
  cap: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  const claimDates = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
    [claims],
  );
  const history = settings?.history;
  const floorOn = useCallback((date: string) => valueOn(history?.floor, date, DEFAULT_FLOOR), [history]);
  const latePctOn = useCallback((date: string) => valueOn(history?.['late-pct'], date, DEFAULT_LATE_PCT), [history]);
  return {
    floorOn,
    latePctOn,
    today,
    policyDate: settings?.policyDate || today,
    cap: settings?.cap ?? '',
    claimDates,
  };
}
